package com.franco.desco.adapter.in.web.access;
import com.franco.desco.application.access.RoleCommands.*; import com.franco.desco.application.shared.pagination.PageRequest; import com.franco.desco.domain.access.RoleModels; import org.springframework.stereotype.Component;
@Component public class RoleWebMapper{
 public ListRoles list(int p,int s){return new ListRoles(new PageRequest<>(p,s,null,null,null));} public CreateRole command(RoleRequests.Create r){return new CreateRole(r.codigo(),r.nombre(),r.descripcion(),r.requiereSegundoFactor());} public UpdateRole command(Long id,RoleRequests.Update r){return new UpdateRole(id,r.nombre(),r.descripcion(),r.requiereSegundoFactor());} public DisableRole command(Long id,RoleRequests.Disable r){return new DisableRole(id,r.motivo());} public UpdatePermissions command(Long id,RoleRequests.Permissions r){return new UpdatePermissions(id,r.permisoIds(),r.motivo());}
 public RoleResponses.Summary response(RoleModels.Summary x){return new RoleResponses.Summary(x.rolId(),x.codigo(),x.nombre(),x.descripcion(),x.requiereSegundoFactor(),x.esSistema(),x.estado(),x.usuariosActivos(),x.permisosActivos());} public RoleResponses.Detail response(RoleModels.Detail x){return new RoleResponses.Detail(response(x.rol()),x.permisos().stream().map(p->new RoleResponses.Permission(p.permisoId(),p.codigo(),p.nombre(),p.accion(),p.esSensible(),p.requiereMotivo(),p.moduloCodigo(),p.moduloNombre(),p.estado())).toList(),x.usuarios().stream().map(u->new RoleResponses.User(u.usuarioId(),u.nombreUsuario(),u.numeroDocumento(),u.empleado(),u.fechaDesde(),u.fechaHasta(),u.estado())).toList());}
}
